<script setup lang="ts">import{computed,onMounted,ref}from"vue";import BaseEmptyState from"@/components/base/BaseEmptyState.vue";import BaseMetricCard from"@/components/base/BaseMetricCard.vue";import BasePageHeader from"@/components/base/BasePageHeader.vue";import BasePagination from"@/components/base/BasePagination.vue";import LibraryCopyDialog from"@/components/library/LibraryCopyDialog.vue";import LibraryLoanDialog from"@/components/library/LibraryLoanDialog.vue";import LoanHistoryPanel from"@/components/library/LoanHistoryPanel.vue";import{buildLibraryDashboard}from"@/domain/library/dashboard";import{editionTypeRepository,libraryCopyRepository,loanHistoryRepository,physicalFormatRepository}from"@/domain/library/repository";import type{EditionTypeRecord,LibraryCopyRecord,LoanHistoryRecord,PhysicalFormatRecord}from"@/domain/library/records";const items=ref<LibraryCopyRecord[]>([]),history=ref<LoanHistoryRecord[]>([]),formats=ref<PhysicalFormatRecord[]>([]),editions=ref<EditionTypeRecord[]>([]),loading=ref(true),historyLoading=ref(true),error=ref(""),page=ref(1),pages=ref(1),search=ref(""),status=ref(""),format=ref(""),edition=ref(""),location=ref(""),dialogOpen=ref(false),editing=ref<LibraryCopyRecord|null>(null),loanOpen=ref(false),loanCopy=ref<LibraryCopyRecord|null>(null);const dashboard=computed(()=>buildLibraryDashboard(items.value,history.value));const filtered=computed(()=>items.value.filter(item=>{const q=search.value.toLocaleLowerCase("pt-PT"),title=item.expand?.titulo?.titulo||"",hay=`${title} ${item.codigo_interno||""} ${item.codigo_barras||""}`.toLocaleLowerCase("pt-PT");return(!q||hay.includes(q))&&(!status||(status==="available"?!item.emprestado:item.emprestado))&&(!format||item.formato===format)&&(!edition||item.tipo_edicao===edition)&&(!location||item.localizacao?.toLocaleLowerCase("pt-PT").includes(location.toLocaleLowerCase("pt-PT")))}));async function load(){loading.value=true;error.value="";try{const[r,f,e]=await Promise.all([libraryCopyRepository.list({page:page.value,perPage:50,sort:"-updated",expand:"titulo,formato,tipo_edicao,emprestado_a"}),physicalFormatRepository.list({page:1,perPage:500,filter:"ativo = true",sort:"categoria,ordem,nome"}),editionTypeRepository.list({page:1,perPage:200,filter:"ativo = true",sort:"categoria,ordem,nome"})]);items.value=r.items;pages.value=r.totalPages||1;formats.value=f.items;editions.value=e.items}catch(c){error.value=c instanceof Error?c.message:String(c)}finally{loading.value=false}}async function loadHistory(){historyLoading.value=true;try{history.value=(await loanHistoryRepository.list({page:1,perPage:500,sort:"-data_emprestimo",expand:"titulo,exemplar,pessoa"})).items}catch(c){error.value=c instanceof Error?c.message:String(c)}finally{historyLoading.value=false}}function create(){editing.value=null;dialogOpen.value=true}function edit(copy:LibraryCopyRecord){editing.value=copy;dialogOpen.value=true}function manageLoan(copy:LibraryCopyRecord){loanCopy.value=copy;loanOpen.value=true}async function saved(){dialogOpen.value=false;loanOpen.value=false;editing.value=null;loanCopy.value=null;await Promise.all([load(),loadHistory()])}function clear(){search.value="";status.value="";format.value="";edition.value="";location.value=""}onMounted(()=>Promise.all([load(),loadHistory()]));</script><template><BasePageHeader eyebrow="Coleção física" title="Biblioteca" description="Exemplares, edições, localização e empréstimos."><template #actions><button class="button button-primary" type="button" @click="create">＋ Novo exemplar</button></template></BasePageHeader><div v-if="error" class="form-alert form-alert-error" role="alert">{{error}}</div><section class="stats-grid compact-stats"><BaseMetricCard icon="▤" label="Exemplares" :value="dashboard.total" detail="nesta página"/><BaseMetricCard icon="◇" label="Disponíveis" :value="dashboard.available" detail="na coleção" tone="cyan"/><BaseMetricCard icon="↗" label="Emprestados" :value="dashboard.borrowed" detail="fora da coleção" tone="amber"/><BaseMetricCard icon="!" label="Em atraso" :value="dashboard.overdue" detail="devolução vencida" tone="pink"/></section><section class="panel library-filters" aria-labelledby="library-filters-title"><div class="library-filter-header"><h2 id="library-filters-title">Pesquisar e filtrar</h2><button class="button button-secondary" type="button" @click="clear">Limpar</button></div><label class="form-field field-wide"><span>Pesquisa</span><input v-model.trim="search" type="search" placeholder="Título, código interno ou código de barras"/></label><label class="form-field"><span>Estado</span><select v-model="status"><option value="">Todos</option><option value="available">Disponíveis</option><option value="borrowed">Emprestados</option></select></label><label class="form-field"><span>Formato</span><select v-model="format"><option value="">Todos</option><option v-for="x in formats" :key="x.id" :value="x.id">{{x.nome}}</option></select></label><label class="form-field"><span>Tipo de edição</span><select v-model="edition"><option value="">Todos</option><option v-for="x in editions" :key="x.id" :value="x.id">{{x.nome}}</option></select></label><label class="form-field"><span>Localização</span><input v-model.trim="location" placeholder="Estante, divisão ou caixa"/></label></section><p v-if="loading" class="page-loading" aria-live="polite">A carregar exemplares…</p><BaseEmptyState v-else-if="!filtered.length" icon="▤" title="Sem exemplares" description="Não existem exemplares para os filtros selecionados."/><div v-else class="table-wrap"><table><thead><tr><th>Título</th><th>Formato</th><th>Edição</th><th>Códigos</th><th>Localização</th><th>Estado</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td><strong>{{item.expand?.titulo?.titulo||'Título desconhecido'}}</strong><small v-if="item.expand?.titulo?.ano">{{item.expand.titulo.ano}}</small></td><td>{{item.expand?.formato?.nome||'—'}}</td><td>{{item.expand?.tipo_edicao?.nome||'—'}}</td><td><small>{{item.codigo_interno||'Sem código interno'}}</small><small>{{item.codigo_barras||'Sem código de barras'}}</small></td><td>{{item.localizacao||'—'}}</td><td>{{item.emprestado?'Emprestado':'Disponível'}}</td><td><div class="library-row-actions"><button class="button button-secondary" type="button" @click="edit(item)">Editar</button><button class="button button-primary" type="button" @click="manageLoan(item)">{{item.emprestado?'Gerir empréstimo':'Emprestar'}}</button></div></td></tr></tbody></table></div><BasePagination :page="page" :pages="pages" label="Paginação dos exemplares" @change="page=$event;load()"/><LoanHistoryPanel :items="history" :loading="historyLoading"/><LibraryCopyDialog :open="dialogOpen" :copy="editing" @close="dialogOpen=false" @saved="saved"/><LibraryLoanDialog :open="loanOpen" :copy="loanCopy" @close="loanOpen=false" @saved="saved"/></template>
